// Normalise the form into the settings every later step reads.
const form = $input.first().json;
const question = String(form.question || '').trim();
const depth = String(form.depth || 'Standard');
const subQuestionCount = depth.startsWith('Quick') ? 3 : depth.startsWith('Thorough') ? 5 : 4;
return [{ json: { question, depth, subQuestionCount, today: $now.toFormat('yyyy-MM-dd') } }];

// The planner decides what to search for; this decides how many searches run.
// Each search is one request to DuckDuckGo, which blocks an IP after roughly
// fifteen in a few minutes, so the count comes from the form, never the model.
const settings = $('Research settings').first().json;
const output = $input.first().json.output || {};
const planned = Array.isArray(output.sub_questions) ? output.sub_questions : [];
const seen = new Set();
const items = [];
for (const p of planned) {
  const question = String((p && p.question) || '').trim();
  const query = String((p && p.search_query) || question)
    .replace(/["']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
  const key = query.toLowerCase();
  if (!question || !query || seen.has(key)) continue;
  seen.add(key);
  items.push({ json: { index: items.length + 1, question, search_query: query } });
  if (items.length >= settings.subQuestionCount) break;
}
if (items.length === 0) {
  items.push({ json: { index: 1, question: settings.question, search_query: settings.question.slice(0, 120) } });
}
return items;

// Always returns exactly one item for the sub-question, whatever the search
// did. A sub-question that silently vanished here would vanish from the
// report too, and the report would read as complete.
const sub = $('Loop over sub-questions').first().json;
const results = $input.all().map((i) => i.json);

const failure = results.find((r) => r.error);
const blocked = !!failure && /challenge|bot-detection|back-off|not sent|rate.?limit|too many requests|access denied|unusual search|status code (403|429)/i.test(String(failure.error));

// Text that is a page's furniture rather than its content: consent walls,
// "enable JavaScript" shells, paywall teasers. It passes a length check, so it
// is caught by what it says.
const WALL = /enable javascript|accept (all )?cookies|cookie (policy|settings|consent)|subscribe to (continue|read)|access denied|are you a robot|you are (a )?human/i;

// The host of an address, by plain string steps; an address with a user name or a backslash in it shows one site and may lead to another.
const hostOf = (url) => {
  const s = String(url || '').trim();
  const lower = s.toLowerCase();
  const rest = lower.startsWith('https://') ? s.slice(8) : lower.startsWith('http://') ? s.slice(7) : '';
  if (rest === '') return '';
  let host = rest;
  for (const stop of ['/', '?', '#']) if (host.includes(stop)) host = host.slice(0, host.indexOf(stop));
  if (host.includes('@') || host.includes('\\')) return '';
  if (host.includes(':')) host = host.slice(0, host.indexOf(':'));
  host = host.toLowerCase();
  while (host.endsWith('.')) host = host.slice(0, -1);
  return host.startsWith('www.') ? host.slice(4) : host;
};
// The site behind a host name: blog.example.com and example.com are one site, example.co.uk keeps three labels.
const SECOND = ['co', 'com', 'org', 'net', 'gov', 'edu', 'ac', 'or', 'ne', 'go'];
const siteOf = (host) => {
  const parts = host.split('.');
  if (parts.length <= 2 || parts.every((p) => p !== '' && !Number.isNaN(Number(p)))) return host;
  const take = parts[parts.length - 1].length === 2 && SECOND.includes(parts[parts.length - 2]) ? 3 : 2;
  return parts.slice(-take).join('.');
};

const sources = [];
for (const r of results) {
  if (!r.url || r.error) continue;
  const content = typeof r.pageContent === 'string' ? r.pageContent.trim() : '';
  const garbled = (content.match(/\ufffd/g) || []).length > content.length * 0.01;
  const isPage = !r.pageContentError && content.length >= 400 && !garbled && !WALL.test(content.slice(0, 800));
  const host = hostOf(r.url);
  if (!host) continue;
  const text = isPage ? content : String(r.description || '').trim();
  if (text.length < 80) continue;
  sources.push({
    title: String(r.pageTitle || r.title || host).slice(0, 200),
    url: r.url,
    host,
    site: siteOf(host),
    published: r.pagePublished || null,
    kind: isPage ? 'page' : 'snippet',
    text,
  });
}

const pages = sources.filter((s) => s.kind === 'page');
const pageSites = new Set(pages.map((s) => s.site));
let status = 'no_evidence';
if (blocked) status = 'blocked';
else if (pages.length >= 2 && pageSites.size >= 2) status = 'ok';
else if (sources.length > 0) status = 'thin';

return [{
  json: {
    index: sub.index,
    subQuestion: sub.question,
    searchQuery: sub.search_query,
    status,
    error: failure ? String(failure.error) : null,
    sources,
  },
}];

// Sources are numbered here, in code, so the model can only ever cite an id
// that exists; it never writes a URL. The same page found by two
// sub-questions is one source, and one site gives at most two sources, so a
// single site cannot be most of the evidence. Ids are never changed later:
// the second round only adds new ones.
const graded = $input.all().map((i) => i.json).sort((a, b) => a.index - b.index);
const settings = $('Research settings').first().json;
const MAX_PER_SITE = 2;

// Plain string steps: the parts of an address, and a key that is the same for the same page with tracking parameters or a trailing slash.
const partsOf = (url) => {
  const s = String(url || '').trim();
  const lower = s.toLowerCase();
  const rest = lower.startsWith('https://') ? s.slice(8) : lower.startsWith('http://') ? s.slice(7) : '';
  if (rest === '') return null;
  const noHash = rest.includes('#') ? rest.slice(0, rest.indexOf('#')) : rest;
  const q = noHash.indexOf('?');
  const beforeQuery = q >= 0 ? noHash.slice(0, q) : noHash;
  const slash = beforeQuery.indexOf('/');
  let host = slash >= 0 ? beforeQuery.slice(0, slash) : beforeQuery;
  let path = slash >= 0 ? beforeQuery.slice(slash) : '';
  if (host.includes('@') || host.includes('\\')) return null;
  if (host.includes(':')) host = host.slice(0, host.indexOf(':'));
  host = host.toLowerCase();
  while (host.endsWith('.')) host = host.slice(0, -1);
  if (host.startsWith('www.')) host = host.slice(4);
  while (path.endsWith('/')) path = path.slice(0, -1);
  return { host, path, query: q >= 0 ? noHash.slice(q + 1) : '' };
};
