const keyOf = (url) => {
  const p = partsOf(url);
  if (!p) return '';
  const query = p.query.split('&').filter((x) => x !== '' && !x.toLowerCase().startsWith('utm_') && !TRACKING.includes(x.split('=')[0].toLowerCase())).sort().join('&');
  return (p.host + p.path + (query ? '?' + query : '')).toLowerCase();
};
