const SECOND = ['co', 'com', 'org', 'net', 'gov', 'edu', 'ac', 'or', 'ne', 'go'];
const siteOf = (host) => {
  const parts = host.split('.');
  if (parts.length <= 2 || parts.every((p) => p !== '' && !Number.isNaN(Number(p)))) return host;
  const take = parts[parts.length - 1].length === 2 && SECOND.includes(parts[parts.length - 2]) ? 3 : 2;
  return parts.slice(-take).join('.');
};

const byKey = new Map();
const perSite = new Map();
const sources = [];
let skippedBySite = 0;
const subQuestions = graded.map((g) => {
  const ids = [];
  // a readable page takes a place before a search snippet does
  const ordered = g.sources.filter((s) => s.kind === 'page').concat(g.sources.filter((s) => s.kind !== 'page'));
  for (const s of ordered) {
    const key = keyOf(s.url);
    if (!key) continue;
    let source = byKey.get(key);
    if (!source) {
      if ((perSite.get(s.site) || 0) >= MAX_PER_SITE) { skippedBySite += 1; continue; }
      source = Object.assign({ id: 'S' + (sources.length + 1), round: 1 }, s);
      byKey.set(key, source);
      perSite.set(s.site, (perSite.get(s.site) || 0) + 1);
      sources.push(source);
    }
    if (!ids.includes(source.id)) ids.push(source.id);
  }
  return { index: g.index, question: g.subQuestion, searchQuery: g.searchQuery, status: g.status, error: g.error, sourceIds: ids };
});

const okCount = subQuestions.filter((s) => s.status === 'ok').length;
const blockedCount = subQuestions.filter((s) => s.status === 'blocked').length;
const blocked = blockedCount > 0;
// Only stop here when there is nothing to work with. Whether what was read
// answers the question is decided after extraction, by the checked findings:
// many research pages refuse to be fetched, and their search snippets still
// carry quotable statements.
const enough = sources.length >= 3 && blockedCount * 2 < subQuestions.length;

// Page text is untrusted: any of it may be written to steer a model. Each
// source is fenced with a marker that includes a per-run nonce, so a page
// cannot forge the end of its own fence.
const nonce = Array.from({ length: 3 }, () => Math.random().toString(36).slice(2, 8)).join('');
const fence = (list) => list.map((s) => [
  '<<<SOURCE ' + s.id + ' ' + nonce + '>>>',
  'Title: ' + s.title,
  'Site: ' + s.host + (s.published ? ' (published ' + s.published + ')' : ''),
  'Kind: ' + (s.kind === 'page' ? 'full page text' : 'search snippet only'),
  'Text:',
  s.text,
  '<<<END ' + s.id + ' ' + nonce + '>>>',
].join('\n')).join('\n\n');
const evidence = fence(sources);

const plan = subQuestions.map((s) => s.index + '. ' + s.question +
  (s.sourceIds.length ? '  [sources: ' + s.sourceIds.join(', ') + ']' : '  [no sources found]')).join('\n');

return [{
  json: {
    question: settings.question,
    today: settings.today,
    nonce,
    round: 1,
    enough,
    blocked,
    okCount,
    skippedBySite,
    usedQueries: graded.map((g) => g.searchQuery),
    subQuestions,
    sources,
    plan,
    evidence,
  },
}];

// A finding survives only if its quote really is in the source it names and its claim says nothing the quote does not. This is what keeps
// the report tied to what was read rather than to what the model remembers. The node runs twice when a second round is needed: the second
// time it reads the merged list of sources and adds to the findings of the first round.
// The first run reads the numbered sources; the run after "Add the new sources" (the second one) reads the merged list.
const bundle = $runIndex > 0 ? $('Add the new sources').first().json : $('Number the sources').first().json;
