const trimEllipsis = (s) => {
  let t = String(s || '').trim();
  while (t.startsWith('...') || t.startsWith('\u2026')) t = t.slice(t.startsWith('\u2026') ? 1 : 3).trim();
  while (t.endsWith('...') || t.endsWith('\u2026')) t = t.slice(0, t.endsWith('\u2026') ? -1 : -3).trim();
  return t;
};
// Every number of the claim must stand in the quote: "40%" for a quote that says 4.0% is not a finding.
const numbersOf = (s) => (String(s || '').normalize('NFKC').match(/\p{Nd}+(?:[.,]\p{Nd}+)*/gu) || []).map((n) => n.split(',').join(''));

const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const allowed = new Set(round >= 2 ? bundle.gapIndexes : bundle.subQuestions.map((s) => s.index));
const kept = previous.kept.slice();
let discarded = previous.discarded;
const seen = new Set(kept.map((v) => v.sourceId + '|' + v.subQuestion + '|' + normalise(v.quote)));

