  // The model sometimes writes the id as "S1 k3j9x2" (the marker's per-run code), "[S1]" or "Source 1".
  const idMatch = String((f && f.source_id) || '').trim().match(/^\W*(?:source\s*)?s?\s*0*([0-9]+)/i);
  const source = idMatch ? byId.get('S' + idMatch[1]) : undefined;
  const trimmed = trimEllipsis(f && f.quote);
  const quote = normalise(trimmed);
  // one line: a claim with line breaks could pose as headings or list items in the text the writer gets
  const claim = String((f && f.claim) || '').replace(/\s+/g, ' ').trim();
  const inside = !trimmed.includes('...') && !trimmed.includes('\u2026');
  const longEnough = quote.length >= 20 && quote.split(' ').length >= 8;
  const quoteNumbers = numbersOf(quote);
  const numbersFit = numbersOf(claim).every((n) => quoteNumbers.includes(n));
  const ok = source && claim !== '' && inside && longEnough && numbersFit && allowed.has(Number(f.sub_question)) &&
    normalise(source.text).includes(quote);
  if (!ok) { discarded += 1; continue; }
  // The prompt asks for at most six per sub-question; enforced here, where it
  // cannot make the output parser reject the whole answer.
  if (kept.filter((v) => v.subQuestion === Number(f.sub_question)).length >= 6) continue;
  const key = source.id + '|' + Number(f.sub_question) + '|' + quote;
  if (seen.has(key)) continue;
  seen.add(key);
  kept.push({
    sourceId: source.id,
    url: source.url,
    subQuestion: Number(f.sub_question),
    claim: claim.slice(0, 500),
    quote: trimmed.slice(0, 400),
    round,
  });
}

const lines = bundle.subQuestions.map((s) => {
  const mine = kept.filter((v) => v.subQuestion === s.index);
  const header = '### ' + s.index + '. ' + s.question + ' (' + s.sourceIds.length + ' sources read' +
    (s.status === 'blocked' ? ', search blocked' : '') + ')';
  if (mine.length === 0) return header + '\n- No checked finding: the sources read did not support an answer.';
  return header + '\n' + mine.map((v) => '- [' + v.sourceId + '] ' + v.claim + ' (quote: "' + v.quote + '")').join('\n');
}).join('\n\n');

// Two checked findings is the least a report can rest on; below that the
// writer would be filling the page from memory.
const enough = kept.length >= 2;

return [{
  json: {
    round,
    question: bundle.question,
    today: bundle.today,
    kept,
    discarded,
    keptCount: kept.length,
    modelFailed,
    enough,
    findingsForWriter: lines,
    bundle: {
      round,
      subQuestions: bundle.subQuestions,
      sources: bundle.sources,
      usedQueries: bundle.usedQueries,
      skippedBySite: bundle.skippedBySite,
      gapIndexes: bundle.gapIndexes || [],
    },
  },
}];

// A sub-question without a single checked finding is a gap. One more round of searches may fill it, with a rewritten query; the rest
// is decided here, in code, never by the model: the round is run once, for at most two sub-questions, and not at all when
// DuckDuckGo has blocked a search (more requests would only make the block last longer).
const checks = $input.first().json;
const bundle = checks.bundle;
const MAX_GAPS = 2;

const covered = new Set(checks.kept.map((v) => v.subQuestion));
const gaps = bundle.subQuestions.filter((s) => !covered.has(s.index) && s.status !== 'blocked');
const anyBlocked = bundle.subQuestions.some((s) => s.status === 'blocked');

let retry = false;
let why = '';
if (checks.modelFailed) why = 'The model did not return findings, so no more searches were sent.';
else if (bundle.round >= 2) why = 'The second round has run.';
else if (gaps.length === 0) why = 'Every sub-question that could be searched has a checked finding.';
else if (anyBlocked) why = 'DuckDuckGo blocked a search, so no more searches were sent.';
else retry = true;

return [{
  json: {
    ...checks,
    retry,
    retryWhy: why,
    gapCount: gaps.length,
    gaps: retry ? gaps.slice(0, MAX_GAPS).map((g) => ({ index: g.index, question: g.question, searchQuery: g.searchQuery })) : [],
  },
}];

