const gapIndexes = Array.from(foundNow.keys());
const plan = gapIndexes.map((i) => {
  const sub = subQuestions.find((s) => s.index === i);
  const ids = foundNow.get(i);
  return i + '. ' + sub.question + (ids.length ? '  [sources: ' + ids.join(', ') + ']' : '  [no sources found]');
