return [{
  json: {
    question: state.question,
    today: state.today,
    nonce,
    round: 2,
    gapIndexes,
    skippedBySite,
    usedQueries: bundle.usedQueries.concat(graded.map((g) => g.searchQuery)),
    subQuestions,
    sources,
    plan,
    evidence,
    previous: { kept: state.kept, discarded: state.discarded },
