// The model wrote prose with [S#] markers. Everything a reader can click, and
// every claim about coverage, is added here from data, not taken from the model.
const checks = $('Any checked findings?').first().json;
const bundle = checks.bundle;
// A report is a few thousand characters; a text far beyond that is a model that does not stop, and the patterns below must not be
// given an unbounded text. Runs of spaces and tabs are collapsed first, because they are what makes a pattern slow.
const MAX_BODY = 24000;
let body = String($input.first().json.text || '').replace(/[ \t]{2,}/g, ' ').slice(0, MAX_BODY);

// Takes out every word that is a web address, whatever it is wrapped in.
const withoutAddresses = (text) => text.replace(/\S+/g, (w) => {
  const lower = w.toLowerCase();
  return lower.includes('://') || lower.startsWith('www.') ? '' : w;
});

// The model's output is text, and it stays text: tags, images and links are
// removed before it is rendered, whatever a source may have told it to write.
// A link target may hold one level of parentheses, as in javascript:alert(1).
body = body
  .replace(/```[a-z]*\n?|```/gi, '')
  .replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, '')
  .replace(/<\/?[a-z!][^<>]*>/gi, '')
  // An unclosed tag would otherwise swallow text up to the next '>'.
  .replace(/<\/?[a-z!][^<>\n]*$/gim, '')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/!\[[^\]]*\]\((?:[^()]|\([^()]*\))*\)/g, '')
  .replace(/\[([^\]\n]{1,300})\]\((?:[^()]|\([^()]*\))*\)/g, '$1')
