  // one, [text][ref] stays plain text. Bare addresses would be auto-linked.
  .replace(/^ {0,3}\[[^\]\n]{1,300}\]:.*$/gm, '')
  .replace(/\[([^\]\n]{1,300})\]\[(?!S\d)[^\]\n]{0,300}\]/g, '$1')
  // What is left of a link, a definition or a scheme that can run code is not a link any more.
  .replace(/\]\(/g, '] (')
  .replace(/\[(?!S\d)([^\]\n]{1,300})\]:/g, '[$1] :')
  .replace(/(?:javascript|vbscript)\s*:|data\s*:\s*(?:text|image|application)/gi, '');
