// A full stop after an abbreviation or an initial does not end a sentence: cutting there would leave a piece without a citation,
// and the piece would be dropped with the claim it belongs to.
const ABBREVIATIONS = ['mr', 'mrs', 'ms', 'dr', 'prof', 'sr', 'jr', 'st', 'vs', 'etc', 'inc', 'ltd', 'co', 'no', 'fig', 'approx'];
