  '# ' + escapeMd(oneLine(checks.question)),
  header,
  body.trim(),
  '## Evidence coverage',
  coverage.join('\n'),
  '## Sources',
  references.length ? sourcesNote + '\n\n' + references.join('\n') : '_No source was cited._',
